window.COURSE.notes["hv"] = [{"n": 1, "title": "Introduction to Value Education", "tagline": "Human Values & Professional Ethics · module 1", "minutes": 7, "sections": [{"kind": "concept", "num": "1", "title": "Quick Map of CO1", "html": "<pre class=\"code\"><code>Value Education → Self-Exploration → Human Aspirations (Happiness + Prosperity)\n        ↓                                        ↓\n  6 Guidelines                    Right Understanding + Relationship + Physical Facility\n        ↓                                        ↓\nNatural Acceptance vs Acceptance         SVDD / SSDD / SSSS categories\n                                                  ↓\n                                    Desires: Preconditioning, Sensation, Natural Acceptance\n                                                  ↓\n                                        Body as Instrument of 'I'\n</code></pre>"}, {"kind": "concept", "num": "2", "title": "VALUE EDUCATION", "html": "<h4>1.1 Meaning</h4>\n<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th>Component</th>\n<th>What it means</th>\n<th>Related to</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Understanding what to do</strong></td>\n<td>Knowing what is valuable as a human being</td>\n<td>Value Education</td>\n</tr>\n<tr>\n<td><strong>Learning how to do</strong></td>\n<td>Acquiring skills &amp; technology</td>\n<td>Technical Education</td>\n</tr>\n</tbody>\n</table></div>\n<blockquote>\n<p><strong>Key line for exam:</strong> <em>\"Value Education tells us what is valuable; Technical Education tells us how to accomplish it.\"</em></p>\n</blockquote>\n<p>⚠️ <strong>Priority order:</strong> Understanding \"what to do\" <strong>comes before</strong> learning \"how to do it.\"</p>\n<p><strong>One-line example to remember:</strong> A technically brilliant person without the understanding of <em>how technology should be used responsibly</em> cannot live a harmonious life.</p>\n<h4>1.2 Need for Value Education</h4>\n<p>Current education overemphasizes skills/technology → but skills alone can't tell us what is valuable.</p>\n<p><strong>Why we need it (list form — good for \"list any 4\" type questions):</strong></p>\n<ol>\n<li>To understand <em>what to do</em></li>\n<li>To develop a holistic perspective</li>\n<li>To understand human values</li>\n<li>To ensure proper use of knowledge &amp; technology</li>\n<li>To develop harmony at 4 levels — individual, family, society, nature</li>\n<li>To avoid problems from wrong understanding</li>\n</ol>\n<blockquote>\n<p><strong>Mnemonic:</strong> <strong>H-U-P-H</strong> → <em>Holistic view, Understanding values, Proper use of tech, Harmony at all levels</em></p>\n</blockquote>\n<h4>1.3 Six Basic Guidelines of Value Education</h4>\n<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th>#</th>\n<th>Guideline</th>\n<th>Meaning</th>\n<th>Trigger word</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1</td>\n<td><strong>Universal</strong></td>\n<td>Applies to all humans, places, times — no caste/creed/gender bias</td>\n<td>\"for everyone, always\"</td>\n</tr>\n<tr>\n<td>2</td>\n<td><strong>Rational</strong></td>\n<td>Logical, questionable, verifiable — not blind belief/dogma</td>\n<td>\"makes sense\"</td>\n</tr>\n<tr>\n<td>3</td>\n<td><strong>Natural</strong></td>\n<td>Naturally acceptable; nature supports its fulfilment; no force needed</td>\n<td>\"feels right without pressure\"</td>\n</tr>\n<tr>\n<td>4</td>\n<td><strong>Verifiable</strong></td>\n<td>Check via Natural Acceptance + real-life experience (mutual happiness with humans, mutual prosperity with nature)</td>\n<td>\"test it in real life\"</td>\n</tr>\n<tr>\n<td>5</td>\n<td><strong>All-Encompassing</strong></td>\n<td>Covers all dimensions (thought, behaviour, work, understanding) &amp; all levels (individual, family, society, nature)</td>\n<td>\"covers everything\"</td>\n</tr>\n<tr>\n<td>6</td>\n<td><strong>Leading to Harmony</strong></td>\n<td>Produces harmony — within self, with others, with nature</td>\n<td>\"creates balance\"</td>\n</tr>\n</tbody>\n</table></div>\n<blockquote>\n<p><strong>Mnemonic to recall all 6:</strong> <strong>U-R-N-V-A-H</strong> → <em>\"Universal, Rational, Natural, Verifiable, All-encompassing, Harmony\"</em></p>\n</blockquote>\n<p><strong>Sub-point for #5 (commonly asked separately):</strong></p>\n<ul>\n<li><strong>4 Individual dimensions:</strong> Thought → Behaviour → Work → Understanding/Realization</li>\n<li><strong>4 Levels of living:</strong> Individual → Family → Society → Nature/Existence</li>\n</ul>\n<h4>1.4 Natural Acceptance vs Acceptance</h4>\n<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th>Natural Acceptance</th>\n<th>Acceptance</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>What's acceptable to us when we have <strong>independent choice</strong></td>\n<td>What we accept due to <strong>circumstances</strong></td>\n</tr>\n<tr>\n<td>Does <strong>not</strong> change with time/place/conditioning</td>\n<td>Influenced by peer pressure, conditioning, sensation, social influence</td>\n</tr>\n<tr>\n<td>Constant &amp; universal</td>\n<td>Variable &amp; situational</td>\n</tr>\n</tbody>\n</table></div>\n<blockquote>\n<p><strong>Exam tip:</strong> If asked to differentiate, always anchor on the word <strong>\"independent choice\"</strong> vs <strong>\"external influence.\"</strong></p>\n</blockquote>"}, {"kind": "concept", "num": "3", "title": "SELF-EXPLORATION", "html": "<h4>2.1 Meaning</h4>\n<ul>\n<li>A process of <strong>knowing oneself</strong>, and through the self, knowing <strong>nature and entire existence</strong>.</li>\n<li>Involves a <strong>dialogue</strong> between:</li>\n<li><strong>What I am</strong> (current state)</li>\n<li><strong>What I really want to be / Natural Acceptance</strong> (desired state)</li>\n</ul>\n<h4>2.2 Purpose</h4>\n<ul>\n<li>Know yourself &amp; your Natural Acceptance</li>\n<li>Understand relationships, human conduct, relation with nature</li>\n<li>Live in harmony with self, others, and existence</li>\n</ul>\n<h4>2.3 Process of Self-Exploration (4 steps — very commonly asked in order)</h4>\n<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th>Step</th>\n<th>Action</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1. <strong>Investigation</strong></td>\n<td>Inquire into self — \"What do I really want? What makes me happy?\"</td>\n</tr>\n<tr>\n<td>2. <strong>Analysis</strong></td>\n<td>Examine information, desires, thoughts, consequences carefully</td>\n</tr>\n<tr>\n<td>3. <strong>Evaluation</strong></td>\n<td>Check if understanding/action matches Natural Acceptance</td>\n</tr>\n<tr>\n<td>4. <strong>Explore</strong></td>\n<td>Continue inquiry to discover truth &amp; live harmoniously</td>\n</tr>\n</tbody>\n</table></div>\n<blockquote>\n<p><strong>Mnemonic:</strong> <strong>I-A-E-E</strong> → <em>Investigate, Analyse, Evaluate, Explore</em></p>\n</blockquote>"}, {"kind": "concept", "num": "4", "title": "MUTUAL HAPPINESS AND MUTUAL PROSPERITY", "html": "<h4>3.1 Basic Human Aspirations</h4>\n<ol>\n<li><strong>Continuous Happiness</strong></li>\n<li><strong>Prosperity</strong></li>\n</ol>\n<h4>3.2 Happiness vs Unhappiness</h4>\n<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th>Term</th>\n<th>Definition</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Happiness</strong></td>\n<td>= Harmony — state of harmony/synergy, naturally acceptable</td>\n</tr>\n<tr>\n<td><strong>Unhappiness</strong></td>\n<td>= Disharmony — state of contradiction</td>\n</tr>\n<tr>\n<td><strong>Continuous Happiness</strong></td>\n<td>Harmony at <strong>all</strong> levels: individual, family, society, nature</td>\n</tr>\n</tbody>\n</table></div>\n<h4>3.3 Prosperity</h4>\n<ul>\n<li><strong>Definition:</strong> Feeling of having <strong>more than required</strong> physical facility.</li>\n<li><strong>Two requirements:</strong></li>\n<li><strong>Identification</strong> of required physical facility → with right understanding</li>\n<li><strong>Ensuring availability/production</strong> of more than required → with right skills</li>\n</ul>\n<blockquote>\n<p><strong>Quick formula:</strong>\n<strong>Prosperity = Right Identification (Understanding) + Right Production/Availability (Skill)</strong></p>\n</blockquote>"}, {"kind": "concept", "num": "5", "title": "RIGHT UNDERSTANDING, RELATIONSHIP & PHYSICAL FACILITIES", "html": "<h4>4.1 Three Basic Requirements</h4>\n<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th>Requirement</th>\n<th>Domain</th>\n<th>Leads to</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Right Understanding</strong></td>\n<td>In the Self</td>\n<td>—</td>\n</tr>\n<tr>\n<td><strong>Relationship</strong></td>\n<td>With Human Beings</td>\n<td>Mutual Happiness</td>\n</tr>\n<tr>\n<td><strong>Physical Facilities</strong></td>\n<td>With rest of Nature</td>\n<td>Mutual Prosperity</td>\n</tr>\n</tbody>\n</table></div>\n<blockquote>\n<p><strong>Correct Priority Order (frequently tested as MCQ/fill-in-blank):</strong>\n<strong>Right Understanding → Relationship → Physical Facilities</strong></p>\n</blockquote>\n<h4>4.2 Animal Consciousness vs Human Consciousness</h4>\n<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th>Animal Consciousness</th>\n<th>Human Consciousness</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Focus mainly on <strong>physical facilities</strong></td>\n<td>Focus on <strong>understanding + relationship + physical facility</strong></td>\n</tr>\n<tr>\n<td>Leads to indefinite conduct</td>\n<td>Leads to <strong>definite</strong> human conduct</td>\n</tr>\n<tr>\n<td>Results in unhappiness/deprivation</td>\n<td>Results in happiness &amp; prosperity</td>\n</tr>\n</tbody>\n</table></div>"}, {"kind": "concept", "num": "6", "title": "TWO (THREE) CATEGORIES OF PERSONS", "html": "<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th>Code</th>\n<th>Full Form</th>\n<th>Meaning</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>SVDD</strong></td>\n<td>Sadhan Viheen Dukhi Daridra</td>\n<td>Lacking physical facility → unhappy &amp; deprived</td>\n</tr>\n<tr>\n<td><strong>SSDD</strong></td>\n<td>Sadhan Sampann Dukhi Daridra</td>\n<td>Has physical facility → <strong>still</strong> unhappy &amp; deprived</td>\n</tr>\n<tr>\n<td><strong>SSSS</strong></td>\n<td>Sadhan Sampann Sukhi Samriddha</td>\n<td>Has physical facility → happy &amp; prosperous ✅ (<strong>goal state</strong>)</td>\n</tr>\n</tbody>\n</table></div>\n<blockquote>\n<p><strong>Key insight for exam:</strong> SSDD proves that <strong>physical facility alone ≠ happiness</strong> — this is the whole justification for needing Right Understanding &amp; Relationship, not just Physical Facilities.</p>\n</blockquote>\n<h4>Current Problems at Four Levels (classic 4-mark question)</h4>\n<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th>Level</th>\n<th>Problems</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Individual</strong></td>\n<td>Depression, anxiety, stress, insecurity</td>\n</tr>\n<tr>\n<td><strong>Family</strong></td>\n<td>Breakup of joint families, mistrust, divorce</td>\n</tr>\n<tr>\n<td><strong>Society</strong></td>\n<td>Violence, terrorism, corruption, exploitation</td>\n</tr>\n<tr>\n<td><strong>Nature/Environment</strong></td>\n<td>Global warming, weather imbalance, deforestation</td>\n</tr>\n</tbody>\n</table></div>"}, {"kind": "concept", "num": "7", "title": "METHOD TO FULFIL BASIC HUMAN ASPIRATIONS", "html": "<h4>6.1 Three Sources of Desire</h4>\n<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th>Source</th>\n<th>Meaning</th>\n<th>Example</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Preconditioning</strong></td>\n<td>From society/family/culture/ads</td>\n<td>Wanting branded clothes for status</td>\n</tr>\n<tr>\n<td><strong>Sensation</strong></td>\n<td>From sensory pleasure (taste, sight, sound)</td>\n<td>Craving junk food</td>\n</tr>\n<tr>\n<td><strong>Natural Acceptance</strong></td>\n<td>From inner self / true clarity</td>\n<td>Wanting to live peacefully, help others</td>\n</tr>\n</tbody>\n</table></div>\n<blockquote>\n<p><strong>Exam trick:</strong> Only desires from <strong>Natural Acceptance</strong> are considered <em>true/correct</em> desires; the other two are externally driven and don't guarantee lasting happiness.</p>\n</blockquote>\n<h4>6.2 Body as an Instrument of 'I'</h4>\n<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th>Role of 'I'</th>\n<th>Explanation</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>I am the Seer</strong></td>\n<td>Eyes are just instruments; 'I' interpret/relate the images to meaning</td>\n</tr>\n<tr>\n<td><strong>I am the Doer</strong></td>\n<td>'I' decide to act, using hands/feet as tools</td>\n</tr>\n<tr>\n<td><strong>I am the Enjoyer</strong></td>\n<td>'I' actually experience taste &amp; enjoyment through the body</td>\n</tr>\n</tbody>\n</table></div>\n<blockquote>\n<p><strong>One-liner:</strong> Body = <strong>instrument</strong>; <strong>'I' (the self)</strong> = the one who sees, does, and enjoys <strong>through</strong> the body.</p>\n</blockquote>"}, {"kind": "revision", "num": "", "title": "Rapid Revision Table (30-second recap before exam)", "html": "<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th>Concept</th>\n<th>One-line Answer</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Value Education</td>\n<td>Tells us <em>what</em> is valuable</td>\n</tr>\n<tr>\n<td>Technical Education</td>\n<td>Tells us <em>how</em> to do it</td>\n</tr>\n<tr>\n<td>6 Guidelines</td>\n<td>Universal, Rational, Natural, Verifiable, All-encompassing, Harmony</td>\n</tr>\n<tr>\n<td>Natural Acceptance</td>\n<td>Independent-choice acceptance, doesn't change</td>\n</tr>\n<tr>\n<td>Self-Exploration steps</td>\n<td>Investigate → Analyse → Evaluate → Explore</td>\n</tr>\n<tr>\n<td>Basic Aspirations</td>\n<td>Continuous Happiness + Prosperity</td>\n</tr>\n<tr>\n<td>Happiness</td>\n<td>= Harmony</td>\n</tr>\n<tr>\n<td>Prosperity</td>\n<td>More than required physical facility</td>\n</tr>\n<tr>\n<td>Priority order</td>\n<td>Right Understanding → Relationship → Physical Facilities</td>\n</tr>\n<tr>\n<td>SSSS</td>\n<td>Sadhan Sampann Sukhi Samriddha (final goal)</td>\n</tr>\n<tr>\n<td>Desire sources</td>\n<td>Preconditioning, Sensation, Natural Acceptance</td>\n</tr>\n<tr>\n<td>Body's role</td>\n<td>Instrument for Seer, Doer, Enjoyer ('I')</td>\n</tr>\n</tbody>\n</table></div>"}, {"kind": "concept", "num": "8", "title": "Likely Exam Questions (self-test)", "html": "<ol>\n<li>Define Value Education and differentiate it from Technical Education.</li>\n<li>List and explain the six basic guidelines of Value Education.</li>\n<li>Differentiate between Natural Acceptance and Acceptance with examples.</li>\n<li>Explain the four steps of Self-Exploration.</li>\n<li>What is the difference between Happiness and Prosperity?</li>\n<li>Explain the correct priority order of Right Understanding, Relationship, and Physical Facilities with reasoning.</li>\n<li>Differentiate Animal Consciousness from Human Consciousness.</li>\n<li>Explain SVDD, SSDD, and SSSS with the significance of the SSDD category.</li>\n<li>List problems arising at the four levels (individual, family, society, nature).</li>\n<li>Explain the three sources of desire with examples.</li>\n<li>Explain \"Body as an instrument of 'I'\" — Seer, Doer, Enjoyer.</li>\n</ol>"}], "practice": [], "file": "Semester_1/Human-Values-Notes/Module1-Notes.md"}, {"n": 2, "title": "Understanding Harmony in the Human Being", "tagline": "Human Values & Professional Ethics · module 2", "minutes": 6, "sections": [{"kind": "concept", "num": "1", "title": "Quick Map of CO2", "html": "<pre class=\"code\"><code>Human Being = 'I' (Self) + Body (co-existing)\n        ↓                    ↓\n   Needs: Happiness      Needs: Physical Facilities\n        ↓                    ↓\n   Body = Instrument of 'I' (Seer, Doer, Enjoyer)\n        ↓\n   Activities of Self → Harmony in 'I' (Right Understanding)\n        ↓\n   Harmony of 'I' with Body → Sanyam + Health\n</code></pre>"}, {"kind": "concept", "num": "2", "title": "HUMAN BEING AS A CO-EXISTENCE OF 'I' AND 'BODY'", "html": "<h4>1.1 Introduction</h4>\n<ul>\n<li>A human being = co-existence of two distinct entities: <strong>Self ('I')</strong> and <strong>Body</strong>.</li>\n<li>Both are <strong>fundamentally different</strong> in nature, needs, and activities — yet work together in close relationship.</li>\n</ul>\n<h4>1.2 Comparison Table (very high-yield — memorize this row by row)</h4>\n<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th>Feature</th>\n<th>Self ('I')</th>\n<th>Body</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Nature</strong></td>\n<td>Sentient (conscious, non-physical)</td>\n<td>Material (physico-chemical, physical)</td>\n</tr>\n<tr>\n<td><strong>Needs</strong></td>\n<td>Happiness (Sukh) — continuous</td>\n<td>Physical Facilities (Suvidha) — temporary</td>\n</tr>\n<tr>\n<td><strong>Time Scale</strong></td>\n<td>Continuous / Permanent</td>\n<td>Temporary (has a life span)</td>\n</tr>\n<tr>\n<td><strong>Means of Fulfillment</strong></td>\n<td>Right Understanding &amp; Right Feeling</td>\n<td>Physical Facilities</td>\n</tr>\n<tr>\n<td><strong>Activities</strong></td>\n<td>Desiring, thinking, imagining, knowing</td>\n<td>Eating, breathing, walking, growing</td>\n</tr>\n</tbody>\n</table></div>\n<blockquote>\n<p><strong>Exam anchor phrase:</strong> <em>\"'I' is Sentient, Body is Material — 'I' wants Happiness (continuous), Body wants Facility (temporary).\"</em></p>\n</blockquote>"}, {"kind": "concept", "num": "3", "title": "NEEDS OF THE SELF AND THE BODY", "html": "<h4>2.1 Needs of the Self ('I') — Happiness (Sukh)</h4>\n<ul>\n<li><strong>Qualitative</strong> — about feeling respected, trusted, happy.</li>\n<li><strong>Continuous in time</strong> — we want it <em>permanently</em>, not intermittently.</li>\n</ul>\n<h4>2.2 Needs of the Body — Physical Facilities (Suvidha)</h4>\n<ul>\n<li><strong>Quantitative</strong> — needed in a <em>limited/finite</em> quantity (e.g., food only up to a point).</li>\n<li><strong>Temporary in time</strong> — needed <em>periodically</em>, not continuously.</li>\n</ul>\n<h4>Comparison Snapshot</h4>\n<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th>Aspect</th>\n<th>Happiness (Self)</th>\n<th>Physical Facility (Body)</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Type</td>\n<td>Qualitative</td>\n<td>Quantitative</td>\n</tr>\n<tr>\n<td>Quantity needed</td>\n<td>Not applicable (a feeling)</td>\n<td>Limited/finite</td>\n</tr>\n<tr>\n<td>Time needed</td>\n<td>Continuous</td>\n<td>Periodic/Temporary</td>\n</tr>\n</tbody>\n</table></div>\n<blockquote>\n<p><strong>Mnemonic:</strong> <strong>Self = Sukh = Sentient = Steady (continuous)</strong>; <strong>Body = Suvidha = Substance = Sometimes (temporary)</strong></p>\n</blockquote>"}, {"kind": "concept", "num": "4", "title": "THE BODY AS AN INSTRUMENT OF 'I'", "html": "<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th>Role of 'I'</th>\n<th>Explanation</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>I am the Seer</strong></td>\n<td>Eyes don't see by themselves — the Self sees <em>through</em> the eyes</td>\n</tr>\n<tr>\n<td><strong>I am the Doer</strong></td>\n<td>The Self decides the action, then uses hands/legs/body parts to execute it</td>\n</tr>\n<tr>\n<td><strong>I am the Enjoyer</strong></td>\n<td>Body only receives the <em>touch</em>; the Self experiences the <em>taste and enjoyment</em></td>\n</tr>\n</tbody>\n</table></div>\n<blockquote>\n<p><strong>Key exam line:</strong> <em>\"The Body acts as an instrument of the Self ('I').\"</em>\nThe body senses/executes; the <strong>'I' interprets, decides, and enjoys</strong>.</p>\n</blockquote>"}, {"kind": "concept", "num": "5", "title": "ACTIVITIES AND HARMONY IN THE SELF ('I')", "html": "<h4>4.1 Four Continuous Activities of the Self</h4>\n<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th>#</th>\n<th>Activity</th>\n<th>Meaning</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1</td>\n<td><strong>Imaging</strong></td>\n<td>Creating desires, pictures, or expectations</td>\n</tr>\n<tr>\n<td>2</td>\n<td><strong>Analyzing</strong></td>\n<td>Breaking down thoughts, weighing options</td>\n</tr>\n<tr>\n<td>3</td>\n<td><strong>Selecting / Tasting</strong></td>\n<td>Choosing what aligns with desires; experiencing the \"taste\" of things</td>\n</tr>\n<tr>\n<td>4</td>\n<td><strong>Realization &amp; Understanding</strong></td>\n<td>Gaining absolute clarity and right understanding</td>\n</tr>\n</tbody>\n</table></div>\n<blockquote>\n<p><strong>Mnemonic:</strong> <strong>I-A-S-R</strong> → <em>Imaging, Analyzing, Selecting, Realization</em></p>\n</blockquote>\n<h4>4.2 Harmony in the Self</h4>\n<ul>\n<li>Harmony in 'I' = <strong>no contradiction</strong> between desires, thoughts, and expectations.</li>\n<li>Achieved through <strong>Right Understanding</strong>.</li>\n</ul>\n<blockquote>\n<p><strong>One-liner:</strong> <em>Harmony in 'I' = Right Understanding → no internal contradiction.</em></p>\n</blockquote>"}, {"kind": "concept", "num": "6", "title": "HARMONY OF 'I' WITH THE BODY — SANYAM AND HEALTH", "html": "<h4>5.1 Definitions</h4>\n<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th>Term</th>\n<th>Meaning</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Sanyam (Self-regulation)</strong></td>\n<td>The feeling of <strong>responsibility</strong> in 'I' for <strong>nurturing, protecting, and rightly utilizing</strong> the Body</td>\n</tr>\n<tr>\n<td><strong>Health (Swasthya)</strong></td>\n<td>State of the Body where <strong>every part performs its expected function correctly</strong></td>\n</tr>\n</tbody>\n</table></div>\n<blockquote>\n<p><strong>Key distinction:</strong> <strong>Sanyam</strong> is a responsibility that lies in the <strong>Self</strong> (towards the body); <strong>Health</strong> is a <em>state</em> of the <strong>Body itself</strong>.</p>\n</blockquote>\n<h4>5.2 Programs to Ensure Sanyam and Health</h4>\n<p><strong>For Sanyam:</strong></p>\n<ul>\n<li>Right understanding about the body</li>\n<li>Consuming physical facilities only <strong>as necessary</strong> — not out of greed or taste alone</li>\n</ul>\n<p><strong>For Health (4 pillars — commonly asked as a list):</strong></p>\n<ol>\n<li><strong>Proper intake</strong> — nutritious food &amp; water</li>\n<li><strong>Proper labour (श्रम)</strong> — physical exercise</li>\n<li><strong>Proper rest &amp; regulation</strong></li>\n<li><strong>Protection</strong> from adverse elements + <strong>right treatment</strong> when ill (avoiding chemical misuse)</li>\n</ol>\n<blockquote>\n<p><strong>Mnemonic for Health pillars:</strong> <strong>I-L-R-P</strong> → <em>Intake, Labour, Rest, Protection</em></p>\n</blockquote>"}, {"kind": "revision", "num": "", "title": "Rapid Revision Table (30-second recap before exam)", "html": "<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th>Concept</th>\n<th>One-line Answer</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Human Being</td>\n<td>Co-existence of 'I' (Self) and Body</td>\n</tr>\n<tr>\n<td>Self ('I') nature</td>\n<td>Sentient, needs Happiness (continuous)</td>\n</tr>\n<tr>\n<td>Body nature</td>\n<td>Material, needs Physical Facility (temporary)</td>\n</tr>\n<tr>\n<td>Happiness</td>\n<td>Qualitative, continuous</td>\n</tr>\n<tr>\n<td>Physical Facility</td>\n<td>Quantitative, limited/temporary</td>\n</tr>\n<tr>\n<td>Body's role</td>\n<td>Instrument of 'I' — Seer, Doer, Enjoyer</td>\n</tr>\n<tr>\n<td>4 Activities of Self</td>\n<td>Imaging, Analyzing, Selecting/Tasting, Realization</td>\n</tr>\n<tr>\n<td>Harmony in 'I'</td>\n<td>No contradiction — via Right Understanding</td>\n</tr>\n<tr>\n<td>Sanyam</td>\n<td>Self's responsibility to nurture/protect/rightly use Body</td>\n</tr>\n<tr>\n<td>Health</td>\n<td>Body's state where every part functions correctly</td>\n</tr>\n<tr>\n<td>4 pillars of Health</td>\n<td>Intake, Labour (श्रम), Rest, Protection</td>\n</tr>\n</tbody>\n</table></div>"}, {"kind": "concept", "num": "7", "title": "Likely Exam Questions (self-test)", "html": "<ol>\n<li>Explain the human being as a co-existence of 'I' and Body, with a comparison table.</li>\n<li>Differentiate between the needs of the Self and the needs of the Body.</li>\n<li>Why is Happiness called \"continuous\" and Physical Facility called \"temporary\"? Explain with examples.</li>\n<li>Explain \"Body as an instrument of 'I'\" using the Seer, Doer, and Enjoyer concept.</li>\n<li>List and explain the four continuous activities of the Self.</li>\n<li>What is meant by \"Harmony in the Self\"? How is it achieved?</li>\n<li>Define Sanyam and Health. How are they different?</li>\n<li>List the programs/measures to ensure Sanyam and Health.</li>\n<li>Explain why physical facilities alone cannot ensure happiness (link to Self vs Body needs).</li>\n</ol>"}], "practice": [], "file": "Semester_1/Human-Values-Notes/Module2-Notes.md"}, {"n": 3, "title": "Harmony in the Family and Society", "tagline": "Human Values & Professional Ethics · module 3", "minutes": 6, "sections": [{"kind": "concept", "num": "1", "title": "Quick Map of CO3", "html": "<pre class=\"code\"><code>Family = Basic Unit / Natural Laboratory of Harmony\n        ↓\nRelationship (already exists) → Feelings exist between 'I' and 'I' (not body)\n        ↓\n9 Definite Feelings/Values (Trust → ... → Love)\n        ↓\n   TRUST (foundation)              RESPECT (right evaluation)\n        ↓                                   ↓\nIntention vs Competence          Over/Under/Otherwise evaluation\n        ↓                                   ↓\nDual Standard Error              False bases (Body, Facility, Belief)\n                                            ↓\n                                  True basis: Self — Purpose, Program,\n                                  Potential, Competence &amp; Complementarity\n                                            ↓\n                          Right Eval → Self-Confidence | Over-Eval → Ego\n                                  Under/Otherwise Eval → Depression\n</code></pre>"}, {"kind": "concept", "num": "2", "title": "HARMONY IN THE FAMILY — THE BASIC UNIT OF HUMAN INTERACTION", "html": "<h4>1.1 Family as the Basic Unit</h4>\n<ul>\n<li><strong>Definition:</strong> Family (<em>Parivara</em>) = a group of individuals living in a relationship of <strong>mutual fulfillment</strong> to ensure <strong>right understanding and prosperity</strong> for all.</li>\n<li><strong>Natural Laboratory:</strong> Family is where we first <strong>learn and practice</strong> harmony in relationships, mutual happiness &amp; evaluation — later <strong>extended to society and nature</strong>.</li>\n<li><strong>Web of Interdependency:</strong> Life is supported by a wider social order too — friends, teachers, neighbours, shopkeepers, milkmen, helpers. Family = <strong>foundation of society</strong>, ensures <strong>continuity of human tradition</strong>.</li>\n</ul>\n<blockquote>\n<p><strong>Exam anchor:</strong> <em>\"Family is the natural laboratory to understand and practice harmony, before extending it to society &amp; nature.\"</em></p>\n</blockquote>\n<h4>1.2 Core Dimensions of Harmony in the Family</h4>\n<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th>Dimension</th>\n<th>Explanation</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Relationship Is</strong></td>\n<td>Relationships <strong>already exist</strong> between Self (I₁) and Self (I₂). Not invented/created — we're <strong>born into them</strong>; we only need to <strong>recognize &amp; understand</strong> them</td>\n</tr>\n<tr>\n<td><strong>The Self Has Feelings</strong></td>\n<td>Feelings exist <strong>between Self and Self</strong>, not at the body level. (E.g., a mother's connection to her child is felt at the level of the Self, not the body)</td>\n</tr>\n<tr>\n<td><strong>Feelings Are Definite</strong></td>\n<td>There are <strong>9 definite feelings/values</strong> — identifiable with clarity</td>\n</tr>\n</tbody>\n</table></div>\n<h4>The 9 Definite Feelings (Values) — HIGH-YIELD, memorize in order</h4>\n<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th>#</th>\n<th>Feeling</th>\n<th>Sanskrit term</th>\n<th>Notes</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1</td>\n<td><strong>Trust</strong></td>\n<td>Vishwas</td>\n<td><strong>Foundation Value</strong></td>\n</tr>\n<tr>\n<td>2</td>\n<td><strong>Respect</strong></td>\n<td>Samman</td>\n<td></td>\n</tr>\n<tr>\n<td>3</td>\n<td><strong>Affection</strong></td>\n<td>Sneha</td>\n<td></td>\n</tr>\n<tr>\n<td>4</td>\n<td><strong>Care</strong></td>\n<td>Mamta</td>\n<td></td>\n</tr>\n<tr>\n<td>5</td>\n<td><strong>Guidance</strong></td>\n<td>Vatsalya</td>\n<td></td>\n</tr>\n<tr>\n<td>6</td>\n<td><strong>Reverence</strong></td>\n<td>Shraddha</td>\n<td></td>\n</tr>\n<tr>\n<td>7</td>\n<td><strong>Glory</strong></td>\n<td>Gaurav</td>\n<td></td>\n</tr>\n<tr>\n<td>8</td>\n<td><strong>Gratitude</strong></td>\n<td>Kritagyata</td>\n<td></td>\n</tr>\n<tr>\n<td>9</td>\n<td><strong>Love</strong></td>\n<td>Prema</td>\n<td><strong>Complete Value</strong></td>\n</tr>\n</tbody>\n</table></div>\n<blockquote>\n<p><strong>Mnemonic:</strong> <strong>T-R-A-C-G-R-G-G-L</strong> → <em>\"Trust Really Affects Caring, Guiding, Revering, Glorifying, Grateful Love\"</em>\nRemember the <strong>bookends</strong>: Trust = <strong>foundation</strong>, Love = <strong>complete/highest</strong>.</p>\n</blockquote>\n<p><strong>Key line:</strong> Recognizing &amp; fulfilling these 9 feelings → <strong>mutual happiness</strong> &amp; harmonious relationships <strong>without complaints</strong>.</p>"}, {"kind": "concept", "num": "3", "title": "'TRUST' — THE FOUNDATIONAL VALUE", "html": "<h4>2.1 Intention vs. Competence</h4>\n<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th>Term</th>\n<th>Meaning</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Intention</strong></td>\n<td>What one <strong>truly wants</strong> — based on <strong>Natural Acceptance</strong> (always to make self &amp; others happy)</td>\n</tr>\n<tr>\n<td><strong>Competence</strong></td>\n<td>What one is <strong>currently able to do</strong> — sum of desires, thoughts, expectations; can be <strong>flawed</strong> due to lack of right understanding or bad upbringing</td>\n</tr>\n</tbody>\n</table></div>\n<blockquote>\n<p><strong>One-liner:</strong> <em>Intention is always good (Natural Acceptance); Competence can be limited/flawed.</em></p>\n</blockquote>\n<h4>2.2 The Dual Standard Error (very commonly asked)</h4>\n<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th>Who</th>\n<th>Evaluated on</th>\n<th>Result</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Ourselves</strong></td>\n<td>Intention</td>\n<td>We always conclude <em>we are good</em></td>\n</tr>\n<tr>\n<td><strong>Others</strong></td>\n<td>Competence</td>\n<td>When they fail, we doubt their <strong>intention</strong> too → conclude <em>they are bad</em></td>\n</tr>\n</tbody>\n</table></div>\n<p><strong>Impact:</strong></p>\n<ul>\n<li><strong>Doubting intention</strong> → irritation, anger, opposition, relationship breakdown</li>\n<li><strong>Trusting intention</strong> → inner strength, effectiveness, avoids unnecessary hurt</li>\n</ul>\n<blockquote>\n<p><strong>Exam anchor:</strong> <em>\"We judge ourselves by intention, others by competence — this double standard is the root of most relationship conflicts.\"</em></p>\n</blockquote>\n<h4>2.3 Common Misconceptions About Trust</h4>\n<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th>Misconception</th>\n<th>Resolution</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><em>\"How can I trust a stranger / someone with bad intentions?\"</em></td>\n<td>Look past their behaviour/competence to their <strong>core natural acceptance</strong> — they're trapped by wrong assumptions &amp; lack of awareness</td>\n</tr>\n<tr>\n<td><em>\"Won't people take undue advantage of me?\"</em></td>\n<td>People exploit only when <strong>you</strong> lack right understanding. Trusting intention ≠ blind action — you still <strong>evaluate competence</strong> before making practical plans</td>\n</tr>\n</tbody>\n</table></div>"}, {"kind": "concept", "num": "4", "title": "'RESPECT' — AS THE RIGHT EVALUATION", "html": "<h4>3.1 Definition</h4>\n<blockquote>\n<p><strong>Respect = Right Evaluation.</strong> Whenever evaluation is not right → it is <strong>disrespect</strong>.</p>\n</blockquote>\n<h4>3.2 Three Types of Disrespect (Disrespect Categories)</h4>\n<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Meaning</th>\n<th>Example</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Over-evaluation</strong></td>\n<td>Evaluating more than what it is</td>\n<td>Exaggerated praise</td>\n</tr>\n<tr>\n<td><strong>Under-evaluation</strong></td>\n<td>Evaluating less than what it is</td>\n<td>Calling someone \"good for nothing\"</td>\n</tr>\n<tr>\n<td><strong>Otherwise evaluation</strong></td>\n<td>Evaluating as something <strong>other</strong> than what it is</td>\n<td>Treating a human being like an animal</td>\n</tr>\n</tbody>\n</table></div>\n<blockquote>\n<p><strong>Mnemonic:</strong> <strong>O-U-O</strong> → <em>Over, Under, Otherwise</em></p>\n</blockquote>\n<h4>3.3 False Bases for Respect Today</h4>\n<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th>Category</th>\n<th>Examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Body Attributes</strong></td>\n<td>Sex/Gender, Race/Skin colour, Caste, Age, Physical strength</td>\n</tr>\n<tr>\n<td><strong>Physical Facilities</strong></td>\n<td>Wealth, Post/Position</td>\n</tr>\n<tr>\n<td><strong>Beliefs ('Isms')</strong></td>\n<td>Capitalist, Socialist, Communist, religious sects</td>\n</tr>\n</tbody>\n</table></div>\n<p><strong>Result of these false bases:</strong> Generation gaps, gender conflicts, racial discrimination, class struggles. Attention-seeking acts (extreme stunts, expensive clothes) fetch only <strong>superficial notice</strong>, not <strong>genuine respect</strong>.</p>\n<blockquote>\n<p><strong>Exam anchor:</strong> <em>\"Basing respect on Body, Facility, or Belief → discrimination &amp; conflict, not true respect.\"</em></p>\n</blockquote>\n<h4>3.4 True Basis for Respect: The Self ('I')</h4>\n<p>At the level of the <strong>Self</strong>, every human is similar to me in <strong>4 ways</strong>:</p>\n<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th>#</th>\n<th>Aspect</th>\n<th>Meaning</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1</td>\n<td><strong>Purpose</strong></td>\n<td>Natural Acceptance &amp; desire to be happy — same for all</td>\n</tr>\n<tr>\n<td>2</td>\n<td><strong>Program</strong></td>\n<td>Program for happiness is similar</td>\n</tr>\n<tr>\n<td>3</td>\n<td><strong>Potential</strong></td>\n<td>Potential is identical</td>\n</tr>\n<tr>\n<td>4</td>\n<td><strong>Competence &amp; Complementarity</strong></td>\n<td>We recognize mutual competence; if other has more understanding → we learn; if we have more → we facilitate them <strong>unconditionally</strong></td>\n</tr>\n</tbody>\n</table></div>\n<blockquote>\n<p><strong>Mnemonic:</strong> <strong>P-P-P-C</strong> → <em>Purpose, Program, Potential, Competence &amp; Complementarity</em></p>\n</blockquote>\n<h4>3.5 Psychological States and Evaluation (Very important — 3-way comparison)</h4>\n<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th>Evaluation Type</th>\n<th>Psychological State</th>\n<th>Term</th>\n<th>Effect on Conduct</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Right Evaluation</strong></td>\n<td><strong>Self-Confidence</strong> (Swayam mein Vishwas)</td>\n<td>Self-referential / Swatantrata</td>\n<td><strong>Definite</strong> conduct</td>\n</tr>\n<tr>\n<td><strong>Over-Evaluation</strong></td>\n<td><strong>Ego</strong> (Ahankar)</td>\n<td>Improperly making other the reference point</td>\n<td><strong>Indefinite</strong> conduct</td>\n</tr>\n<tr>\n<td><strong>Under/Otherwise Evaluation</strong></td>\n<td><strong>Depression</strong> (Avsad)</td>\n<td>Feeling helpless/subordinate</td>\n<td><strong>Indefinite</strong> conduct</td>\n</tr>\n</tbody>\n</table></div>\n<blockquote>\n<p><strong>Exam anchor:</strong> <em>Right evaluation → self-confidence &amp; definite conduct; wrong evaluation (over/under/otherwise) → ego or depression &amp; indefinite conduct.</em></p>\n</blockquote>"}, {"kind": "revision", "num": "", "title": "Rapid Revision Table (30-second recap before exam)", "html": "<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th>Concept</th>\n<th>One-line Answer</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Family</td>\n<td>Basic unit / natural laboratory of harmony</td>\n</tr>\n<tr>\n<td>Relationship</td>\n<td>Already exists — we recognize, not create it</td>\n</tr>\n<tr>\n<td>Feelings exist at</td>\n<td>Level of Self, not Body</td>\n</tr>\n<tr>\n<td>9 Feelings</td>\n<td>Trust → Respect → Affection → Care → Guidance → Reverence → Glory → Gratitude → Love</td>\n</tr>\n<tr>\n<td>Foundation value</td>\n<td>Trust</td>\n</tr>\n<tr>\n<td>Complete value</td>\n<td>Love</td>\n</tr>\n<tr>\n<td>Intention</td>\n<td>What we truly want (always good, via Natural Acceptance)</td>\n</tr>\n<tr>\n<td>Competence</td>\n<td>What we're currently able to do (can be flawed)</td>\n</tr>\n<tr>\n<td>Dual Standard Error</td>\n<td>Judge self by intention, others by competence</td>\n</tr>\n<tr>\n<td>Respect</td>\n<td>Right evaluation</td>\n</tr>\n<tr>\n<td>3 types of disrespect</td>\n<td>Over, Under, Otherwise evaluation</td>\n</tr>\n<tr>\n<td>False bases of respect</td>\n<td>Body, Physical Facility, Beliefs (Isms)</td>\n</tr>\n<tr>\n<td>True basis of respect</td>\n<td>Self — Purpose, Program, Potential, Competence &amp; Complementarity</td>\n</tr>\n<tr>\n<td>Right evaluation →</td>\n<td>Self-Confidence, definite conduct</td>\n</tr>\n<tr>\n<td>Over-evaluation →</td>\n<td>Ego, indefinite conduct</td>\n</tr>\n<tr>\n<td>Under/Otherwise evaluation →</td>\n<td>Depression, indefinite conduct</td>\n</tr>\n</tbody>\n</table></div>"}, {"kind": "concept", "num": "5", "title": "Likely Exam Questions (self-test)", "html": "<ol>\n<li>Define family and explain why it is called a \"natural laboratory\" for harmony.</li>\n<li>Explain the statement \"Relationship is\" — why relationships are not created but recognized.</li>\n<li>List and explain the 9 definite feelings/values in human relationships, in order.</li>\n<li>Differentiate between Intention and Competence with examples.</li>\n<li>Explain the \"Dual Standard Error\" in evaluating self vs. others, and its impact on relationships.</li>\n<li>Address the common misconceptions about trust (\"how can I trust a stranger\", \"won't people take advantage of me\").</li>\n<li>Define Respect and explain the three types of disrespect with examples.</li>\n<li>Explain the false bases on which respect is given in society today, and the problems they cause.</li>\n<li>Explain the true basis of respect at the level of the Self (Purpose, Program, Potential, Competence &amp; Complementarity).</li>\n<li>Explain the relationship between evaluation type (right/over/under/otherwise) and psychological states (self-confidence, ego, depression).</li>\n</ol>"}], "practice": [], "file": "Semester_1/Human-Values-Notes/Module3-Notes.md"}, {"n": 4, "title": "Family, Society and Harmony in Relationships", "tagline": "Human Values & Professional Ethics · module 4", "minutes": 6, "sections": [{"kind": "concept", "num": "1", "title": "Family as the Basic Unit of Interaction", "html": "<p><strong>Family (Parivara):</strong> a group of individuals living in a relationship of <strong>mutual fulfillment</strong>, so that each member has <strong>Right Understanding</strong> and <strong>Prosperity</strong>.</p>\n<p><strong>Why the family matters</strong></p>\n<ul>\n<li><strong>Foundation of society:</strong> it is the basic unit of human interaction and carries human tradition forward from one generation to the next.</li>\n<li><strong>Natural laboratory:</strong> the family is where we <em>understand, practice, evaluate and fulfill</em> harmony in relationships. We learn it here first and then extend it to society and nature.</li>\n<li><strong>Web of dependency:</strong> life depends on far more than parents and siblings. It also depends on extended family, friends, teachers, and service providers (grocery shopkeeper, milkman, helper, etc.).</li>\n</ul>"}, {"kind": "concept", "num": "2", "title": "Harmony at Four Levels: Goal vs. Current Misunderstanding", "html": "<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th>Level</th>\n<th>Comprehensive Human Goal</th>\n<th>Gross Misunderstanding (Present State)</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Individual</strong></td>\n<td>Right Understanding and Right Feelings</td>\n<td>Living on assumptions; \"money is everything\"</td>\n</tr>\n<tr>\n<td><strong>Family</strong></td>\n<td>Prosperity</td>\n<td>Accumulation of wealth by any means</td>\n</tr>\n<tr>\n<td><strong>Society</strong></td>\n<td>Fearlessness (based on Trust)</td>\n<td>Domination, exploitation, fear</td>\n</tr>\n<tr>\n<td><strong>Nature</strong></td>\n<td>Co-existence</td>\n<td>Mastery over nature, exploitation, resource depletion</td>\n</tr>\n</tbody>\n</table></div>"}, {"kind": "concept", "num": "3", "title": "Values in Relationship", "html": "<p>The notes build up a chain of values. Each one grows out of the earlier ones.</p>\n<pre class=\"code\"><code>Trust -&gt; Respect -&gt; Affection -&gt; Care / Guidance -&gt; Reverence -&gt; Glory / Gratitude -&gt; Love\n</code></pre>\n<h4>3.1 Trust (Vishwas): the Foundation Value</h4>\n<ul>\n<li><strong>Definition:</strong> being assured that the other person <em>naturally wants my happiness and prosperity</em>.</li>\n<li><strong>The core error we make:</strong></li>\n<li>We judge <strong>ourselves by our intention</strong> (\"I mean well, so I am good\").</li>\n<li>We judge <strong>others by their competence</strong> (\"they made a mistake, so they are bad\").</li>\n<li><strong>Doubting intention</strong> leads to irritation, anger and opposition.</li>\n<li><strong>Trusting intention</strong> keeps the relationship continuous. If the other person lacks competence, we respond with <em>responsibility</em>, helping them improve instead of reacting against them.</li>\n</ul>\n<blockquote>\n<p><strong>Remember:</strong> Intention and competence are different things. Judge intention (which is usually good) separately from competence (which can be improved).</p>\n</blockquote>\n<h4>3.2 Respect (Samman): Right Evaluation</h4>\n<ul>\n<li><strong>Definition:</strong> evaluating a person <strong>correctly</strong> (<em>Samyak Mapan</em>).</li>\n</ul>\n<p><strong>Three forms of disrespect (wrong evaluation)</strong></p>\n<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Meaning</th>\n<th>Example</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Over-evaluation</strong> (Adhimulyan)</td>\n<td>Evaluating <em>more</em> than what it is</td>\n<td>Treating someone as superior because of their post or wealth</td>\n</tr>\n<tr>\n<td><strong>Under-evaluation</strong> (Avamulyan)</td>\n<td>Evaluating <em>less</em> than what it is</td>\n<td>Looking down on someone</td>\n</tr>\n<tr>\n<td><strong>Otherwise evaluation</strong> (Amulyan)</td>\n<td>Evaluating as <em>something else</em></td>\n<td>Calling a human being a donkey</td>\n</tr>\n</tbody>\n</table></div>\n<p><strong>Differentiation vs. Respect</strong></p>\n<ul>\n<li>Society today <strong>confuses differentiation with respect</strong>. It bases \"respect\" on:</li>\n<li><strong>Body:</strong> gender, race, age, physical strength</li>\n<li><strong>Physical facilities:</strong> wealth, post</li>\n<li><strong>Beliefs:</strong> isms, sects</li>\n<li>Differentiation produces <strong>opposition, movements, generation gaps and conflict</strong>.</li>\n<li><strong>Real respect</strong> is based on the <strong>Self (I, the conscious entity)</strong>. Every human being has the same <strong>Purpose, Program and Potential</strong>, and our different <strong>competencies make us complementary</strong> rather than competitors.</li>\n</ul>\n<h4>3.3 Affection (Sneha)</h4>\n<ul>\n<li>The feeling of <strong>being related</strong> to the other.</li>\n<li>It follows naturally from Trust and Respect.</li>\n</ul>\n<h4>3.4 Care (Mamata) and Guidance (Vatsalya)</h4>\n<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th>Value</th>\n<th>Responsibility towards a relative's...</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Care (Mamata)</strong></td>\n<td><strong>Body</strong>: nurturing and protecting it</td>\n</tr>\n<tr>\n<td><strong>Guidance (Vatsalya)</strong></td>\n<td><strong>Self (I)</strong>: ensuring Right Understanding and Right Feeling</td>\n</tr>\n</tbody>\n</table></div>\n<h4>3.5 Reverence (Shraddha)</h4>\n<ul>\n<li><strong>Acceptance of excellence</strong> in another person.</li>\n<li><strong>Excellence vs. being special</strong></li>\n<li><em>Excellence:</em> living in harmony <strong>and helping others reach the same level</strong>.</li>\n<li><em>Being special:</em> competitive; seeks to dominate or hoard.</li>\n</ul>\n<h4>3.6 Glory (Gaurav) and Gratitude (Kritagyata)</h4>\n<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th>Value</th>\n<th>Feeling for...</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Glory (Gaurav)</strong></td>\n<td>Those who have made efforts for <strong>excellence</strong></td>\n</tr>\n<tr>\n<td><strong>Gratitude (Kritagyata)</strong></td>\n<td>Those who have made efforts for <strong>my</strong> excellence</td>\n</tr>\n</tbody>\n</table></div>\n<h4>3.7 Love (Prem): the Complete Value</h4>\n<ul>\n<li>The feeling of being <strong>related to all human beings and all units in existence</strong>.</li>\n<li>It is the foundation of an <strong>Undivided Society (Akhand Samaj)</strong>.</li>\n</ul>"}, {"kind": "concept", "num": "4", "title": "Society: Present State vs. Universal Order", "html": "<h4>Current obsessions (the \"madness\" driving society)</h4>\n<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th>Obsession</th>\n<th>Meaning</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Bhog Unmad</strong></td>\n<td>Madness for consumption</td>\n</tr>\n<tr>\n<td><strong>Labh Unmad</strong></td>\n<td>Madness for profit</td>\n</tr>\n<tr>\n<td><strong>Kama Unmad</strong></td>\n<td>Madness for sensual pleasure</td>\n</tr>\n</tbody>\n</table></div>\n<p>Result: <strong>resource depletion, pollution and war.</strong></p>\n<h4>Three social conditions</h4>\n<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th>Condition</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Society</strong></td>\n<td>People living in <strong>mutual fulfillment</strong></td>\n</tr>\n<tr>\n<td><strong>Crowd</strong></td>\n<td>People living together <strong>without</strong> mutual fulfillment</td>\n</tr>\n<tr>\n<td><strong>Battlefield</strong></td>\n<td>People living in <strong>opposition and struggle</strong></td>\n</tr>\n</tbody>\n</table></div>\n<h4>Five Dimensions of Human Order</h4>\n<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th>Dimension</th>\n<th>Key word</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Education</td>\n<td>Sanskar</td>\n</tr>\n<tr>\n<td>Health</td>\n<td>Sanyam</td>\n</tr>\n<tr>\n<td>Production</td>\n<td>Work</td>\n</tr>\n<tr>\n<td>Justice</td>\n<td>Suraksha</td>\n</tr>\n<tr>\n<td>Exchange</td>\n<td>Storage</td>\n</tr>\n</tbody>\n</table></div>"}, {"kind": "revision", "num": "", "title": "Quick Revision", "html": "<ul>\n<li>Family = mutual fulfillment; first place to practice harmony.</li>\n<li><strong>Trust</strong> is the foundation. Judge intention and competence separately.</li>\n<li><strong>Respect</strong> = right evaluation. Do not confuse it with differentiation by body, wealth or belief.</li>\n<li>Chain of values: Trust, Respect, Affection, Care/Guidance, Reverence, Glory/Gratitude, <strong>Love</strong>.</li>\n<li>Society, Crowd and Battlefield differ by the level of mutual fulfillment.</li>\n</ul>"}], "practice": [], "file": "Semester_1/Human-Values-Notes/Module4-Notes.md"}, {"n": 5, "title": "Gender, Sensitization and Sexual Harassment", "tagline": "Human Values & Professional Ethics · module 5", "minutes": 6, "sections": [{"kind": "concept", "num": "1", "title": "Sex vs. Gender", "html": "<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th>Aspect</th>\n<th><strong>Sex</strong></th>\n<th><strong>Gender</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Nature</td>\n<td>Biological and physiological</td>\n<td>Socially constructed</td>\n</tr>\n<tr>\n<td>Based on</td>\n<td>Anatomy (reproductive organs), chromosomes (XX, XY), genes, hormones (estrogen, testosterone)</td>\n<td>Roles, behaviors, expectations, norms and identities</td>\n</tr>\n<tr>\n<td>Categories</td>\n<td>Male, female, intersex</td>\n<td>Man, woman, non-binary</td>\n</tr>\n<tr>\n<td>Origin</td>\n<td>Natural; assigned at birth</td>\n<td>Sociocultural and psychological; <strong>learned</strong></td>\n</tr>\n<tr>\n<td>Changeability</td>\n<td>Largely fixed</td>\n<td>Evolves across cultures and time</td>\n</tr>\n</tbody>\n</table></div>\n<ul>\n<li><strong>Gender identity:</strong> an individual's deeply felt <strong>internal sense of self</strong>. Learned behaviors and societal expectations shape gender roles and identity.</li>\n<li><strong>Gender studies:</strong> an interdisciplinary field (psychology, sociology, history, political science). It examines how culture and power structures enforce norms of femininity and masculinity, and works towards gender equality and against discrimination.</li>\n</ul>"}, {"kind": "concept", "num": "2", "title": "Key Terminology", "html": "<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th>Term</th>\n<th>Meaning</th>\n<th>Example / Note</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Gender roles</strong></td>\n<td>Behaviors, attitudes and responsibilities expected of people in public and private spheres based on their assigned sex</td>\n<td>Expecting women to manage the household</td>\n</tr>\n<tr>\n<td><strong>Gender stereotyping</strong></td>\n<td>Assigning roles or behaviors based on preconceived prejudice</td>\n<td>\"Women are submissive, men are aggressive\"</td>\n</tr>\n<tr>\n<td><strong>Gender bias</strong></td>\n<td>Preferential or differential treatment based on real or perceived gender</td>\n<td>Unequal treatment at the workplace</td>\n</tr>\n<tr>\n<td><strong>Gender discrimination</strong></td>\n<td>Unequal or disadvantageous treatment based on gender or gender expression</td>\n<td>Pay disparity, restricted education, misgendered speech</td>\n</tr>\n<tr>\n<td><strong>Gender equity</strong></td>\n<td>Being <strong>fair</strong> to all genders through targeted measures that recognize unique needs</td>\n<td>Different support to reach equal outcomes</td>\n</tr>\n<tr>\n<td><strong>Gender gap</strong></td>\n<td>Disparity between men and women in economic participation, salary, political representation, education or culture</td>\n<td>A measurable indicator</td>\n</tr>\n<tr>\n<td><strong>Intersectionality</strong></td>\n<td>Overlap of social identities (race, class, sexual orientation, disability) creating compounded discrimination or privilege</td>\n<td>A disabled woman from a marginalized class faces layered disadvantage</td>\n</tr>\n</tbody>\n</table></div>\n<blockquote>\n<p><strong>Equity vs. Equality:</strong> equality means treating everyone the same. Equity means treating people <em>fairly according to their needs</em> so that outcomes become equal.</p>\n</blockquote>"}, {"kind": "concept", "num": "3", "title": "Gender Sensitization", "html": "<p><strong>Definition:</strong> the process of <strong>creating awareness, examining personal beliefs, and changing stereotyped mindsets</strong> that see men and women as unequal.</p>\n<p><strong>Primary aims</strong></p>\n<ol>\n<li><strong>Attitudinal change:</strong> change age-old traditional views and break rigid stereotypes.</li>\n<li><strong>Shift in focus:</strong> gender is not only about \"women\"; it is about <em>people</em> and human equality.</li>\n<li><strong>Education and awareness:</strong> sensitize adolescent girls and boys to existing inequalities and gender-based violence.</li>\n<li><strong>Inclusivity:</strong> promote peaceful co-existence, mutual respect and dignified lives for all.</li>\n</ol>\n<h4>Challenges in achieving gender equality</h4>\n<ul>\n<li>Gender-based violence</li>\n<li>Pay gap</li>\n<li>Limited representation</li>\n</ul>"}, {"kind": "concept", "num": "4", "title": "LGBTQ: Meaning of Each Letter", "html": "<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th>Letter</th>\n<th>Term</th>\n<th>Meaning</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>L</strong></td>\n<td>Lesbian</td>\n<td>A woman emotionally or romantically attracted to women</td>\n</tr>\n<tr>\n<td><strong>G</strong></td>\n<td>Gay</td>\n<td>A person (often a man) attracted to people of the same gender</td>\n</tr>\n<tr>\n<td><strong>B</strong></td>\n<td>Bisexual</td>\n<td>A person attracted to more than one gender</td>\n</tr>\n<tr>\n<td><strong>T</strong></td>\n<td>Transgender</td>\n<td>A person whose gender identity differs from the sex assigned at birth</td>\n</tr>\n<tr>\n<td><strong>Q</strong></td>\n<td>Queer / Questioning</td>\n<td><em>Queer:</em> umbrella term for non-heterosexual or non-cisgender identities. <em>Questioning:</em> exploring or unsure about one's orientation or identity</td>\n</tr>\n</tbody>\n</table></div>"}, {"kind": "concept", "num": "5", "title": "How to Build Self-Confidence", "html": "<ol>\n<li><strong>Stop comparing</strong> yourself to others.</li>\n<li><strong>Commit to personal growth</strong> and become an expert in your field.</li>\n<li><strong>Face your fears</strong> and step out of your comfort zone.</li>\n<li><strong>Practice positive self-talk.</strong></li>\n</ol>\n<h4>The \"3P HALC\" Formula</h4>\n<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th>Letter</th>\n<th>Stands for</th>\n<th>Meaning</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>P</strong></td>\n<td><strong>Plan</strong></td>\n<td>Have a clear plan</td>\n</tr>\n<tr>\n<td><strong>P</strong></td>\n<td><strong>Positive attitude</strong></td>\n<td>Keep a positive attitude</td>\n</tr>\n<tr>\n<td><strong>P</strong></td>\n<td><strong>Priority</strong></td>\n<td>Follow the principle of priority</td>\n</tr>\n<tr>\n<td><strong>H</strong></td>\n<td><strong>Hard work</strong></td>\n<td>There is no substitute for hard work</td>\n</tr>\n<tr>\n<td><strong>A</strong></td>\n<td><strong>Acquire</strong> education and skills</td>\n<td>Gain relevant education and skills</td>\n</tr>\n<tr>\n<td><strong>L</strong></td>\n<td><strong>Learn</strong> from mistakes</td>\n<td>Treat mistakes as lessons</td>\n</tr>\n<tr>\n<td><strong>C</strong></td>\n<td><strong>Cultivate</strong> good habits</td>\n<td>Build positive habits</td>\n</tr>\n</tbody>\n</table></div>"}, {"kind": "concept", "num": "6", "title": "Sexual Harassment", "html": "<h4>6.1 Definition</h4>\n<p><strong>Unwanted behavior that is sexual in nature.</strong></p>\n<h4>6.2 Four forms</h4>\n<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th>Form</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Verbal</strong></td>\n<td>Unwanted comments or jokes</td>\n</tr>\n<tr>\n<td><strong>Physical</strong></td>\n<td>Unwanted touching or gestures</td>\n</tr>\n<tr>\n<td><strong>Visual</strong></td>\n<td>Offensive images or displays</td>\n</tr>\n<tr>\n<td><strong>Cyber</strong></td>\n<td>Harassment online or through technology platforms</td>\n</tr>\n</tbody>\n</table></div>\n<h4>6.3 Recognizing everyday harassment</h4>\n<ul>\n<li><strong>Unwanted attention:</strong> persisting with uninvited advances or commentary</li>\n<li><strong>Inappropriate touching:</strong> unwanted physical contact or gestures</li>\n<li><strong>Offensive jokes:</strong> suggestive or demeaning humor</li>\n<li><strong>Stalking:</strong> repeated, unwanted contact or communication</li>\n</ul>\n<h4>6.4 Consent and healthy relationships</h4>\n<p>A healthy relationship rests on <strong>clear, enthusiastic agreement, free from coercion.</strong></p>\n<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th>Pillar</th>\n<th>Meaning</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Respect</strong></td>\n<td>Actively valuing others' boundaries</td>\n</tr>\n<tr>\n<td><strong>Communication</strong></td>\n<td>Open and honest conversation</td>\n</tr>\n<tr>\n<td><strong>Equality</strong></td>\n<td>Keeping power dynamics balanced</td>\n</tr>\n</tbody>\n</table></div>\n<h4>6.5 Bystander intervention (the 4 Ds/actions)</h4>\n<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th>Action</th>\n<th>What to do</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Speak up</strong></td>\n<td>Challenge the behavior directly</td>\n</tr>\n<tr>\n<td><strong>Distract</strong></td>\n<td>Change the subject or create a diversion</td>\n</tr>\n<tr>\n<td><strong>Support</strong></td>\n<td>Offer help and comfort to the victim</td>\n</tr>\n<tr>\n<td><strong>Report</strong></td>\n<td>Inform the appropriate authorities</td>\n</tr>\n</tbody>\n</table></div>\n<h4>6.6 Coping strategies for victims</h4>\n<ol>\n<li><strong>Talk</strong> to a trusted friend for emotional support.</li>\n<li><strong>Seek professional help</strong> (counseling or therapy).</li>\n<li><strong>Document</strong> the harassment: exact dates, times, and details.</li>\n<li><strong>Report</strong> officially to a manager, supervisor or HR.</li>\n</ol>\n<h4>6.7 Institutional prevention and culture</h4>\n<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th>Policy element</th>\n<th>Associated procedure</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Non-discrimination policy</td>\n<td>Clear reporting process for complaints</td>\n</tr>\n<tr>\n<td>Harassment prevention training</td>\n<td>Available resources and support services</td>\n</tr>\n</tbody>\n</table></div>\n<p><strong>Building a culture of respect</strong></p>\n<ul>\n<li><strong>Open communication:</strong> encourage honest dialogue</li>\n<li><strong>Training and education:</strong> promote awareness and mutual understanding</li>\n<li><strong>Zero-tolerance policy:</strong> clear, uncompromised consequences for harassment</li>\n</ul>"}, {"kind": "revision", "num": "", "title": "Quick Revision", "html": "<ul>\n<li><strong>Sex</strong> = biological; <strong>Gender</strong> = social and learned.</li>\n<li>Stereotype, bias, discrimination, equity, gap and intersectionality are all distinct terms. Know a one-line definition and example for each.</li>\n<li>Gender sensitization changes <strong>attitudes</strong>, and it concerns people, not only women.</li>\n<li>Harassment forms: <strong>Verbal, Physical, Visual, Cyber.</strong></li>\n<li>Bystander: <strong>Speak up, Distract, Support, Report.</strong></li>\n<li>Victim: <strong>Talk, Seek help, Document, Report.</strong></li>\n</ul>"}], "practice": [], "file": "Semester_1/Human-Values-Notes/Module5-Notes.md"}, {"n": 6, "title": "Existence, Natural Acceptance and Ethical Human Conduct", "tagline": "Human Values & Professional Ethics · module 6", "minutes": 7, "sections": [{"kind": "concept", "num": "1", "title": "Co-Existence in Existence", "html": "<p><strong>Existence</strong> = <strong>units submerged in all-pervading space.</strong></p>\n<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th></th>\n<th><strong>Units (Nature)</strong></th>\n<th><strong>Space</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Size</td>\n<td>Limited</td>\n<td>All-pervading, unlimited</td>\n</tr>\n<tr>\n<td>Activity</td>\n<td>Active</td>\n<td>No activity</td>\n</tr>\n<tr>\n<td>Role</td>\n<td>Self-organized, energized; recognize and fulfill relationships</td>\n<td>Provides the environment for self-organization; background for all units</td>\n</tr>\n<tr>\n<td>Energy</td>\n<td>Energized</td>\n<td>Constant energy; transparent</td>\n</tr>\n</tbody>\n</table></div>\n<h4>The Four Orders of Nature</h4>\n<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th>Order</th>\n<th>Includes</th>\n<th>Characteristic activity</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Material</strong></td>\n<td>Soil, minerals, air, water</td>\n<td>Physical activities</td>\n</tr>\n<tr>\n<td><strong>Pranic</strong></td>\n<td>Plants, flora, biological growth</td>\n<td>Life processes (respiration, growth)</td>\n</tr>\n<tr>\n<td><strong>Animal</strong></td>\n<td>Animal bodies</td>\n<td>Conscious activities</td>\n</tr>\n<tr>\n<td><strong>Human</strong></td>\n<td>Human body + knowledge, physical facilities, consciousness, understanding</td>\n<td>Understanding-based living</td>\n</tr>\n</tbody>\n</table></div>\n<h4>Recyclability and Self-Regulation</h4>\n<ul>\n<li><strong>Recyclability:</strong> material units transform through natural processes and return to their original form (water, oxygen and nitrogen cycles).</li>\n<li><strong>Self-regulation:</strong> nature's inherent balance controls plant and animal populations so all breeds continue to <strong>co-exist without depleting resources.</strong></li>\n<li><strong>Role of education and Sanskar:</strong> helps humans move from unguided living to <strong>definite human conduct</strong>, so they fit into nature's self-regulating harmony.</li>\n</ul>"}, {"kind": "concept", "num": "2", "title": "Natural Acceptance of Human Values", "html": "<ul>\n<li>Human values are <strong>inherent in existence</strong>. They are <strong>discovered through self-exploration, not imposed.</strong></li>\n<li><strong>Do not enforce values through:</strong></li>\n<li><strong>Fear</strong> (Bhaya)</li>\n<li><strong>Greed</strong> (Pralobhana)</li>\n<li><strong>Blind faith/belief</strong> (Astha)</li>\n<li>The right basis is <strong>Right Understanding</strong>, so that values are <em>naturally acceptable</em>.</li>\n</ul>\n<h4>Progression of Self-Realization</h4>\n<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th>Stage</th>\n<th>Meaning</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Swatva</strong> (Innate identity)</td>\n<td>Natural acceptance that is <strong>innate, invariant, universal</strong></td>\n</tr>\n<tr>\n<td><strong>Swatantrata</strong> (Self-organized living)</td>\n<td>Realizing harmony within oneself and living by it</td>\n</tr>\n<tr>\n<td><strong>Swarajya</strong> (Self-expression in society)</td>\n<td>Working to ensure harmony in the larger societal order</td>\n</tr>\n</tbody>\n</table></div>\n<h4>Implications of value-based living</h4>\n<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th>Level</th>\n<th>Outcome</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Individual</strong></td>\n<td>Peace, happiness, contentment, bliss, perseverance, bravery, generosity</td>\n</tr>\n<tr>\n<td><strong>Family</strong></td>\n<td>Mutual fulfillment, prosperity, sustained joint-family structures, respect for all regardless of age, gender, caste, race or status</td>\n</tr>\n<tr>\n<td><strong>Society</strong></td>\n<td>Fearlessness; holistic systems of education, health, justice, production, exchange; global harmony</td>\n</tr>\n<tr>\n<td><strong>Nature</strong></td>\n<td>Co-existence of all units, seasonal balance, resource preservation, a <strong>Universal Human Order</strong></td>\n</tr>\n</tbody>\n</table></div>"}, {"kind": "concept", "num": "3", "title": "Utility Value vs. Artistic Value", "html": "<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th></th>\n<th><strong>Utility Value</strong></th>\n<th><strong>Artistic Value</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Meaning</td>\n<td>Using physical facilities to <strong>nurture, protect and provide</strong> for the body</td>\n<td>Preserving and enhancing the utility of a facility (<strong>right utilization</strong>)</td>\n</tr>\n</tbody>\n</table></div>\n<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th>Item</th>\n<th>Utility value</th>\n<th>Artistic value</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Pen</strong></td>\n<td>Writing</td>\n<td>Leak-proof cap, comfortable grip</td>\n</tr>\n<tr>\n<td><strong>Shirt</strong></td>\n<td>Protects body from weather</td>\n<td>Buttons, proper sizing for comfort</td>\n</tr>\n<tr>\n<td><strong>Food</strong></td>\n<td>Nurtures the body</td>\n<td>Cooking so it is digestible, serving it properly</td>\n</tr>\n</tbody>\n</table></div>\n<blockquote>\n<p><strong>Key principle:</strong> Artistic value exists <strong>only when utility value is already present.</strong> Without utility, art has no scope.</p>\n</blockquote>"}, {"kind": "concept", "num": "4", "title": "Values in Human Relationships", "html": "<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th><strong>Established / Eternal Values</strong> (Sthapit Mulya)</th>\n<th><strong>Expressed / Behavioral Values</strong> (Sisht Mulya)</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Trust (Vishwas)</td>\n<td>Complementariness (Sojanyata)</td>\n</tr>\n<tr>\n<td>Respect (Sammaan)</td>\n<td>Compliance (Arahaysata)</td>\n</tr>\n<tr>\n<td>Affection (Sneh)</td>\n<td>Commitment (Nishtha)</td>\n</tr>\n<tr>\n<td>Care (Mamta)</td>\n<td>Generosity (Udarta)</td>\n</tr>\n<tr>\n<td>Guidance (Vatsalya)</td>\n<td>Spontaneity (Sahajta)</td>\n</tr>\n<tr>\n<td>Reverence (Shraddha)</td>\n<td>Obedience (Pujyata)</td>\n</tr>\n<tr>\n<td>Glory (Gaurav)</td>\n<td>Ease (Saralta)</td>\n</tr>\n<tr>\n<td>Gratitude (Kritagyata)</td>\n<td>Self-restraint (Somyata)</td>\n</tr>\n<tr>\n<td>Love (Prem)</td>\n<td>Unanimity (Ananyata), kindness</td>\n</tr>\n</tbody>\n</table></div>\n<p><em>Note: the two columns are two separate lists of nine. Rows are not matched pairs.</em></p>\n<ul>\n<li><strong>Established values</strong> are the inner feelings that exist in relationships (see CO4 for what each means).</li>\n<li><strong>Expressed values</strong> are how those feelings show up in behavior.</li>\n</ul>"}, {"kind": "concept", "num": "5", "title": "Definiteness of Ethical Human Conduct", "html": "<h4>5.1 Concept of Innateness (Humanness)</h4>\n<ul>\n<li>Everything in nature has a definite innate character: a mango tree has \"mango-ness\", iron has \"iron-ness\", a cow has \"cow-ness\".</li>\n<li>Human beings have a definite innate character called <strong>Humanness (Manavta).</strong></li>\n<li>Right Understanding gained by self-exploration reveals <strong>Ethical Human Conduct (Manaviya Acharan)</strong>, which is <strong>universal and invariant</strong> across all humans.</li>\n<li>Debates about what is \"ethical\" arise only from <strong>lack of Right Understanding.</strong> With it, conduct becomes definite.</li>\n</ul>\n<h4>5.2 Three Dimensions of Definite Ethical Human Conduct (Nischit Manaviya Acharan)</h4>\n<pre class=\"code\"><code>Ethical Human Conduct = Values (Mulya) + Policy (Niti) + Character (Charitra)\n</code></pre>\n<h5>I. Values (Mulya)</h5>\n<ul>\n<li>Universal human values come from <strong>realization and understanding of the harmony</strong> at all levels of existence.</li>\n<li>Once existence is understood, a person's imagination naturally turns toward fulfilling these values through definite participation.</li>\n<li>Categories: <strong>Established values</strong> and <strong>Expressed values</strong> (Section 4).</li>\n</ul>\n<h5>II. Policy (Niti)</h5>\n<ul>\n<li>The <strong>strategic framework or plan</strong> to protect and enrich physical, mental and societal resources in line with Right Understanding.</li>\n</ul>\n<h5>III. Character (Charitra)</h5>\n<p>The actual <strong>external manifestation of consciousness in daily living</strong>, with three pillars:</p>\n<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th>Pillar</th>\n<th>Meaning</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Rightfully acquired wealth</strong> (Swa-Dhan)</td>\n<td>Acquiring resources <strong>without exploitation</strong> (<em>Shoshan Mukt</em>)</td>\n</tr>\n<tr>\n<td><strong>Chastity in relationships</strong> (Swa-Nari / Swa-Purush)</td>\n<td>Loyalty and fidelity in marital relationships</td>\n</tr>\n<tr>\n<td><strong>Compassionate behavior and work</strong> (Dayapurn Vyavahar and Karya)</td>\n<td>Taking responsibility to <strong>fill the gaps created by ignorance</strong>, in human relationships and in work with nature</td>\n</tr>\n</tbody>\n</table></div>"}, {"kind": "concept", "num": "6", "title": "Human Conduct: Animal vs. Human Consciousness", "html": "<h4>Living with Animal Consciousness (lack of Right Understanding)</h4>\n<p>Common root: a <strong>feeling of inability to take care of one's own body.</strong></p>\n<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th>Trait</th>\n<th>How it appears</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Wretchedness</strong> (Deenata)</td>\n<td>Helplessness and total dependence on others</td>\n</tr>\n<tr>\n<td><strong>Cunningness</strong> (Heenata)</td>\n<td>Beguiling or tricking others</td>\n</tr>\n<tr>\n<td><strong>Cruelty</strong> (Kroorata)</td>\n<td>Violence and forcefulness against others</td>\n</tr>\n</tbody>\n</table></div>\n<h4>Living with Human Consciousness (guided by Right Understanding)</h4>\n<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th>Trait</th>\n<th>Meaning</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Perseverance</strong> (Dheerata)</td>\n<td>Assurance that the living solution lies in understanding and living in harmony across all 4 levels; steady commitment without perturbation</td>\n</tr>\n<tr>\n<td><strong>Bravery</strong> (Veerata)</td>\n<td>Commitment to help others develop right understanding and live in harmony</td>\n</tr>\n<tr>\n<td><strong>Generosity</strong> (Udarata)</td>\n<td>Readiness to invest one's self, body and physical facilities to help others gain right understanding</td>\n</tr>\n</tbody>\n</table></div>\n<p><strong>Pairing to remember:</strong>\nWretchedness leads to <strong>Perseverance</strong>, Cunningness leads to <strong>Bravery</strong>, Cruelty leads to <strong>Generosity</strong>.</p>\n<h4>Completion states in a human being</h4>\n<ul>\n<li><strong>Kriyapurnata:</strong> completion of <strong>right understanding.</strong></li>\n<li><strong>Acharanpurnata:</strong> the ability to <strong>live</strong> with complete understanding.</li>\n</ul>"}, {"kind": "concept", "num": "7", "title": "Profession and Its Role in the Larger Order", "html": "<p><strong>Profession:</strong> a significant domain of human activity for participating in the larger order (society and nature), usually centered on production activities.</p>\n<p><strong>Dual role</strong></p>\n<ol>\n<li>Provides physical facilities (<strong>livelihood</strong>) for oneself and one's family.</li>\n<li>Acts as a <strong>channel for meaningful participation and service</strong> to the larger order.</li>\n</ol>\n<p><strong>Ethical conduct in profession</strong> means using professional skills to fulfill the <strong>comprehensive human goal</strong>, the happiness and prosperity of all.</p>\n<p><strong>Professional education:</strong> technical education (e.g., engineering) gives skills, but <strong>ethical competence</strong> is needed to direct those skills toward human welfare.</p>"}, {"kind": "concept", "num": "8", "title": "Five Competencies in Professional Ethics", "html": "<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th>#</th>\n<th>Competence</th>\n<th>What it means</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1</td>\n<td><strong>Clarity on goals</strong></td>\n<td>Understanding the comprehensive human goal (<em>Samadhana-Samriddhi-Abhaya-Sah-astitva</em>), fulfilled through a universal human order from family to world family</td>\n</tr>\n<tr>\n<td>2</td>\n<td><strong>Confidence and harmony</strong></td>\n<td>Self-confidence and faith in the prevailing harmony, co-existence and self-regulation of existence</td>\n</tr>\n<tr>\n<td>3</td>\n<td><strong>Mutually fulfilling behavior</strong></td>\n<td>Ability to build mutually fulfilling relationships, with clarity on ethical conduct, for sustainable individual and collective well-being</td>\n</tr>\n<tr>\n<td>4</td>\n<td><strong>Mutually enriching interaction with nature</strong></td>\n<td>Assessing physical needs accurately and producing facilities through eco-friendly, harmonious production</td>\n</tr>\n<tr>\n<td>5</td>\n<td><strong>Actualization</strong></td>\n<td>Applying and living right understanding in everyday real-life situations</td>\n</tr>\n</tbody>\n</table></div>\n<p><strong>The four parts of the comprehensive human goal</strong>\n| Term | Meaning |\n| --- | --- |\n| <strong>Samadhana</strong> | Resolution / peace (individual) |\n| <strong>Samriddhi</strong> | Prosperity (family) |\n| <strong>Abhaya</strong> | Fearlessness (society) |\n| <strong>Sah-astitva</strong> | Co-existence (nature) |</p>"}, {"kind": "concept", "num": "9", "title": "Present Unethical Practices", "html": "<ul>\n<li>Corruption at multiple levels</li>\n<li>Tax evasion and misuse of public funds</li>\n<li>Misleading advertising, propaganda, aggressive sales tactics</li>\n<li>Cut-throat competition and exploitation of consumer weaknesses</li>\n<li>Adulteration, spurious production, hoarding, over-charging</li>\n<li>Endangering public safety and health</li>\n</ul>\n<p><strong>Underlying cause:</strong> lack of Right Understanding and a misplaced goal (accumulation, profit and consumption). The remedy is Right Understanding, which makes conduct definite and ethical.</p>"}, {"kind": "revision", "num": "", "title": "Quick Revision", "html": "<ul>\n<li>Existence = <strong>units in space</strong>; four orders: Material, Pranic, Animal, Human.</li>\n<li>Values are <strong>discovered by self-exploration</strong>, never enforced by fear, greed or blind faith.</li>\n<li>Swatva, then Swatantrata, then Swarajya.</li>\n<li><strong>Utility</strong> comes first; <strong>artistic value</strong> depends on it.</li>\n<li>Ethical Human Conduct = <strong>Values + Policy + Character.</strong></li>\n<li>Character has three pillars: rightly acquired wealth, chastity, compassionate behavior.</li>\n<li>Animal consciousness (<strong>Deenata, Heenata, Kroorata</strong>) vs. human consciousness (<strong>Dheerata, Veerata, Udarata</strong>).</li>\n<li>Five professional-ethics competencies: goals, harmony, fulfilling behavior, nature interaction, actualization.</li>\n</ul>"}, {"kind": "revision", "num": "", "title": "Master Revision Sheet", "html": "<div class=\"tbl-wrap\"><table>\n<thead>\n<tr>\n<th>Topic</th>\n<th>One-line takeaway</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Family</td>\n<td>Basic unit; practice ground for mutual fulfillment</td>\n</tr>\n<tr>\n<td>Trust</td>\n<td>Believing the other wants my happiness; separate intention from competence</td>\n</tr>\n<tr>\n<td>Respect</td>\n<td>Right evaluation based on the Self, not body, wealth or belief</td>\n</tr>\n<tr>\n<td>Love</td>\n<td>Feeling of relatedness with all; basis of Undivided Society</td>\n</tr>\n<tr>\n<td>Society vs. Crowd vs. Battlefield</td>\n<td>Mutual fulfillment, no fulfillment, opposition</td>\n</tr>\n<tr>\n<td>Sex vs. Gender</td>\n<td>Biological vs. socially constructed</td>\n</tr>\n<tr>\n<td>Gender sensitization</td>\n<td>Changing mindsets; about people, not only women</td>\n</tr>\n<tr>\n<td>Harassment forms</td>\n<td>Verbal, Physical, Visual, Cyber</td>\n</tr>\n<tr>\n<td>Natural acceptance</td>\n<td>Values are innate and discovered, not imposed</td>\n</tr>\n<tr>\n<td>Utility vs. Artistic value</td>\n<td>Artistic value exists only with utility</td>\n</tr>\n<tr>\n<td>Ethical conduct</td>\n<td>Values + Policy + Character</td>\n</tr>\n<tr>\n<td>Profession</td>\n<td>Livelihood plus service to the larger order</td>\n</tr>\n</tbody>\n</table></div>"}], "practice": [], "file": "Semester_1/Human-Values-Notes/Module6-Notes.md"}];
